const stdout = $input.first().json.stdout || '[]';
const docs = JSON.parse(stdout);
const chunkSize = Number($env.STANDARDS_CHUNK_SIZE || 1000);
const overlap = Number($env.STANDARDS_CHUNK_OVERLAP || 180);
const versionFrom = (content) => (content.match(/Version:\s*([^\n]+)/i) || [null, '1.0'])[1].trim();
const categoryFrom = (section) => (section.match(/Category:\s*([^\n]+)/i) || [null, 'General'])[1].trim();
const technologyFrom = (section) => (section.match(/Technology:\s*([^\n]+)/i) || [null, 'All'])[1].trim();
const splitLong = (text) => {
  if (text.length <= chunkSize) return [text];
  const out = [];
  let i = 0;
  while (i < text.length) {
    out.push(text.slice(i, i + chunkSize));
    i += Math.max(1, chunkSize - overlap);
  }
  return out;
};
const items = [];
for (const doc of docs) {
  const version = versionFrom(doc.content);
  const parts = doc.content.split(/\n(?=##\s+)/g).filter((p) => p.trim());
  for (const part of parts) {
    const heading = (part.match(/^##\s+([^\n]+)/m) || [null, doc.source_file])[1].trim();
    const idMatch = heading.match(/^([A-Z]+-[0-9]{3})\s+[—-]\s+(.+)$/);
    const standard_id = idMatch ? idMatch[1] : heading.replace(/\s+/g, '-').toUpperCase();
    const title = idMatch ? idMatch[2] : heading;
    for (const chunk of splitLong(part.trim())) {
      items.push({ json: { standard_id, title, category: categoryFrom(part), technology: technologyFrom(part), source_file: doc.source_file, version, content: chunk, embedding_request: { model: $env.OLLAMA_EMBEDDING_MODEL || 'nomic-embed-text', prompt: `${standard_id} ${title}\n${chunk}` } } });
    }
  }
}
return items;
